<?php include 'admin_auth.php'; if(isset($_POST['add'])){$n=mysqli_real_escape_string($conn,$_POST['category_name']);$d=mysqli_real_escape_string($conn,$_POST['description']);mysqli_query($conn,"INSERT INTO categories(category_name,description) VALUES('$n','$d')");} if(isset($_GET['delete'])){$id=(int)$_GET['delete'];mysqli_query($conn,"DELETE FROM categories WHERE id=$id");header('Location: categories.php');exit;} $cats=mysqli_query($conn,"SELECT * FROM categories"); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Categories</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../assets/css/style.css"></head><body class="bakery-body"><div class="container-fluid"><div class="row"><?php include 'sidebar.php'; ?><main class="col-md-9 col-lg-10 p-4"><h1 class="section-title">Manage Categories</h1><div class="table-card mb-3"><form method="post" class="row g-2"><div class="col-md-4"><input class="form-control" name="category_name" placeholder="Category Name" required></div><div class="col-md-6"><input class="form-control" name="description" placeholder="Description"></div><div class="col-md-2"><button name="add" class="btn btn-maroon w-100">Add</button></div></form></div><div class="table-card"><table class="table"><tr><th>Name</th><th>Description</th><th></th></tr><?php while($c=mysqli_fetch_assoc($cats)): ?><tr><td><?= e($c['category_name']) ?></td><td><?= e($c['description']) ?></td><td><a class="btn btn-sm btn-danger" href="categories.php?delete=<?= $c['id'] ?>">Delete</a></td></tr><?php endwhile; ?></table></div></main></div></div></body></html>
